        {"대지":"서론", "내용":"에돔은 당당하게 선언한다. '다시 쌓으리라.' 그러나 만군의 여호와가 응답하신다. '나는 헐리라.' 인간의 교만한 계획과 하나님의 절대적 주권이 정면으로 충돌한다. 결과는 명백하다. 하나님이 이기신다", "예화_적용":"바벨탑을 쌓던 인간의 교만이 어떻게 끝났는지 기억하라"},
        {"대지":"1대지: 다시 쌓으리라 (인간의 교만)", "내용":"하나님의 심판을 무시하고 자기 힘으로 재건하겠다는 에돔의 오만. 하나님 없이 스스로 해결하겠다는 교만", "예화_적용":"하나님의 경고를 무시하고 내 방식대로 하겠다는 것이 교만의 시작이다"},
        {"대지":"2대지: 나는 헐리라 (하나님의 주권)", "내용":"하나님이 허시면 아무도 세울 수 없음. 하나님의 주권은 인간의 의지를 초월함", "예화_적용":"하나님의 뜻에 순복하는 것이 지혜이다. 대항하면 결국 허물어진다"},
        {"대지":"3대지: 악한 지경과 영영한 진노 (영원한 결과)", "내용":"에돔은 영원히 악한 지경으로 기억됨. 하나님의 진노가 영원히 임한 백성이라 불림", "예화_적용":"일시적 쾌락을 위해 영원한 결과를 감수하지 말라"},
        {"대지":"결론", "내용":"하나님의 주권 앞에 겸손하라. 쌓아도 허시는 하나님과 싸우지 말고 순복하라. 에돔의 교만이 아닌 야곱의 겸손을 선택하라", "예화_적용":"폭풍 앞에서 큰 나무는 부러지나 유연한 풀은 살아남듯 하나님 앞에 겸손한 자가 서 있게 된다"}
