        {"영어원문":"The Lord will be magnified beyond the border of Israel — his dominion extends over all nations.", "한국어번역":"여호와께서 이스라엘 지경 밖에서 크시리라 - 그의 통치가 모든 나라에 미침이라.", "핵심통찰":"하나님의 통치는 모든 나라에 미침"},
        {"영어원문":"God's people should observe his providence and give him glory for it.", "한국어번역":"하나님의 백성은 그의 섭리를 관찰하고 그로 인해 그에게 영광을 돌려야 한다.", "핵심통찰":"하나님의 섭리를 관찰하고 영광 돌려야 함"}
