        {"대지":"서론", "내용":"이스라엘 백성이 에돔의 멸망을 직접 눈으로 보게 된다. 그리고 고백한다. 여호와는 이스라엘 지경 밖에서도 크시다. 하나님은 한 민족의 하나님이 아니라 온 세상의 주권자이시다", "예화_적용":"하나님의 능력이 교회 밖에서도 역사하심을 인정할 때 신앙의 시야가 넓어진다"},
        {"대지":"1대지: 너희는 목도하고 (직접 보는 신앙)", "내용":"하나님의 역사를 소문이 아닌 직접 눈으로 확인. 체험적 신앙의 중요성", "예화_적용":"남의 간증이 아닌 나의 경험으로 하나님을 만나라"},
        {"대지":"2대지: 이스라엘 지경 밖에서 (경계를 초월하심)", "내용":"하나님의 통치가 이스라엘 영토에 한정되지 않음. 보편적 주권", "예화_적용":"하나님은 직장에서도, 학교에서도, 시장에서도 크시다. 삶의 모든 영역의 주인이시다"},
        {"대지":"3대지: 크시다 하리라 (위대하심의 고백)", "내용":"하나님의 역사를 보고 위대하심을 고백하는 것이 올바른 반응", "예화_적용":"일상에서 하나님의 손길을 발견하고 고백하는 습관을 기르라"},
        {"대지":"결론", "내용":"우리의 하나님은 교회 건물 안에만 계신 분이 아니다. 역사를 주관하시고 세상을 통치하시는 만왕의 왕이시다. 이 하나님의 위대하심을 삶의 모든 영역에서 고백하자", "예화_적용":"하나님의 위대하심을 볼 수 있는 눈을 달라고 기도하라"}
