        {"새찬송가":"4", "통일찬송가":"4", "제목":"성부 성자 성령", "선정이유":"삼위 하나님께 드리는 경배"},
        {"새찬송가":"235", "통일찬송가":"230", "제목":"주의 음성을 내가 들으니", "선정이유":"하나님의 질문에 귀 기울이는 자세"},
        {"새찬송가":"492", "통일찬송가":"347", "제목":"비둘기같이 온유한", "선정이유":"겸손히 하나님 앞에 나아감"}
