        {"상황":"하나님에 대한 경외심이 사라진 분", "성경원리":"하나님은 아버지이자 주인이시다. 공경과 경외가 관계의 기본", "실제적용":"하나님의 거룩하심과 위대하심을 묵상하라. 경외심은 하나님의 본성을 알 때 회복된다"},
        {"상황":"영적으로 둔감해진 분", "성경원리":"'어떻게 멸시하였나이까'라는 반문은 영적 둔감함의 표현", "실제적용":"하나님의 말씀 앞에 정직하게 서라. 자기 변호보다 하나님의 진단을 받아들이라"}
