        {"상황":"헌금이나 봉사를 의무감으로 하는 분", "성경원리":"형식적 제물은 하나님을 기쁘시게 하지 못한다. 진심이 담기지 않은 봉사는 경멸이 될 수 있음", "실제적용":"의무감이 아닌 감사함으로 드리라. 하나님의 은혜를 묵상하면 진심이 따라온다"}
