        {"구절":"신 15:21", "연결점":"흠이 있으면 여호와께 잡아 드리지 말라", "구분":"구약"},
        {"구절":"삼상 15:22", "연결점":"순종이 제사보다 나으니", "구분":"구약"},
        {"구절":"잠 3:9", "연결점":"네 재물과 소산의 처음 익은 열매로 여호와를 공경하라", "구분":"구약"},
        {"구절":"마 22:21", "연결점":"가이사의 것은 가이사에게 하나님의 것은 하나님께", "구분":"신약"},
        {"구절":"히 10:5-10", "연결점":"제사와 예물을 원하지 아니하시고 오직 몸을 예비하셨나이다", "구분":"신약"},
        {"구절":"롬 12:1", "연결점":"너희 몸을 하나님이 기뻐하시는 산 제사로", "구분":"신약"},
        {"구절":"고후 8:5", "연결점":"먼저 자신을 주께 드리고", "구분":"신약"}
