        {"항목":"이름을 더럽힘", "내용":"하나님의 이름을 더럽히는 것은 제3계명(출 20:7) 위반. 하나님의 거룩한 이름을 세속화하고 가볍게 만드는 행위", "목회적활용":"하나님의 이름을 높이는 삶이 성도의 기본 사명"}
