        {"영어원문":"The fruit thereof, even his meat, is contemptible — they treated God's provisions with disdain.", "한국어번역":"그 위에 있는 실과 곧 식물은 경멸히 여긴다 - 하나님이 공급하신 것을 멸시로 대했다.", "핵심통찰":"하나님의 공급을 멸시하는 배은망덕"},
        {"영어원문":"Those who profane God's name make themselves vile in the eyes of all.", "한국어번역":"하나님의 이름을 더럽히는 자는 모든 이의 눈에 천해진다.", "핵심통찰":"하나님의 이름을 더럽히면 자신이 천해짐"}
