        {"교리":"부정한 제물의 거부", "설명":"도둑질한 물건을 제물로 드리는 것은 하나님을 도둑의 공범으로 만드는 것. 하나님은 정의를게 얻은 것만 받으심", "관련구절":"사 61:8, 잠 15:8, 잠 21:27, 시 51:16-17"},
        {"교리":"점진적 타락", "설명":"8절의 흠 있는 제물에서 13절의 토색한 물건으로 타락이 점점 심화됨. 작은 타협이 큰 불경건으로 이어짐", "관련구절":"잠 4:14-19, 히 3:13, 약 1:14-15, 갈 5:9"}
