        {"대지":"서론", "내용":"말라기 1장의 마지막 절은 강력한 경고로 끝난다. 좋은 수컷이 있으면서 흠 있는 것으로 바꿔 드리는 사기꾼에게 저주를 선언하신다. 그 이유는 분명하다. 나는 큰 임금이요 내 이름은 열방 중에서 두려움이 되기 때문이다", "예화_적용":"왕 앞에서 사기를 치면 반역죄에 해당하듯 하나님 앞의 기만은 가장 중한 죄이다"},
        {"대지":"1대지: 수컷이 있거늘 흠 있는 것으로 (의도적 사기)", "내용":"좋은 것이 있으면서도 나쁜 것을 드리는 의도적 기만. 하나님을 속이려는 뻔뻔한 시도", "예화_적용":"10만원을 벌고 100원을 헌금하면서 형편이 어렵다고 말하는 것이 아닌지 점검하라"},
        {"대지":"2대지: 저주를 받으리니 (사기의 대가)", "내용":"하나님을 속이는 자에게 축복이 아닌 저주가 임함. 아나니아와 삽비라의 경고", "예화_적용":"하나님을 속이면 일시적으로 이득인 것 같으나 결국 저주를 받는다"},
        {"대지":"3대지: 나는 큰 임금이라 (하나님의 정체성)", "내용":"하나님은 만왕의 왕이시다. 큰 임금에게 합당한 경외와 예물이 필요", "예화_적용":"대통령 앞에서 예를 갖추듯 만왕의 왕이신 하나님 앞에서 더 큰 경외심을 가지라"},
        {"대지":"결론", "내용":"말라기 1장은 하나님의 사랑으로 시작하여 경외로 끝난다. 하나님의 사랑을 의심하지 말고 큰 임금이신 하나님을 속이지 말라. 진심으로, 최선으로, 정직하게 하나님을 섬기자", "예화_적용":"하나님은 모든 것을 아시는 큰 임금이시다. 그분 앞에 정직한 삶을 살자"}
