        {"교리":"하나님의 이름의 영광", "설명":"제사장의 핵심 사명은 하나님의 이름을 영화롭게 하는 것. 이것을 실패하면 모든 복이 무효화됨", "관련구절":"시 29:2, 사 42:8, 요 12:28, 빌 2:9-11"},
        {"교리":"심판의 현재성", "설명":"'이미 저주하였나니'는 심판이 미래 위협이 아닌 현재 진행형임을 선언. 불순종에 대한 결과는 즉각적", "관련구절":"갈 6:7, 민 32:23, 잠 11:21, 호 8:7"}
