        {"항목":"종자 견책의 의미", "내용":"종자는 후손과 농작물 모두를 의미. 자녀의 불행과 농사의 실패가 동시에 예고됨", "목회적활용":"불순종의 결과는 개인을 넘어 가정과 삶의 전 영역에 영향을 미친다"},
        {"항목":"제하여 버림을 당함", "내용":"제사장직에서 쫓겨나 배설물과 함께 진영 밖으로 버려짐. 가장 치욕적인 퇴출", "목회적활용":"하나님이 세우신 자리에서의 퇴출은 가장 두려운 심판이다"}
