        {"대지":"결론", "내용":"하나님은 형식적 예배를 참으시지 않는다. 절기의 화려함 뒤에 진심이 없을 때 그 예배는 배설물에 불과하다. 진정한 예배는 마음의 헌신에서 시작된다", "예화_적용":"예배의 핵심은 형식이 아니라 마음이다"}
