        {"교리":"레위 언약의 의미", "설명":"레위와의 언약은 하나님과 인간 사이의 중보적 사역을 위한 것. 제사장직의 거룩한 목적", "관련구절":"민 25:12-13, 신 33:8-11, 느 13:29, 렘 33:21"}
