    표5_매튜헨리: [
        {"영어원문":"The design of this rebuke is that my covenant with Levi might stand. God's corrections are not to destroy, but to preserve.", "한국어번역":"이 견책의 목적은 레위와의 나의 언약이 서게 하려 함이다. 하나님의 교정은 파괴가 아니라 보존을 위한 것이다.", "핵심통찰":"하나님의 모든 징계는 보존을 목적으로 한다"},
        {"영어원문":"God would have them know that He does not willingly afflict, but chastens that the covenant may continue.", "한국어번역":"하나님은 기꺼이 괴롭히시는 것이 아니라 언약이 계속되도록 징계하시는 것임을 알게 하셨다.", "핵심통찰":"징계의 이면에는 언약을 포기하지 않는 하나님의 사랑이 있다"},
        {"영어원문":"It is a mercy to be told of our faults, for it is in order to the preventing of our ruin.", "한국어번역":"잘못을 지적받는 것은 은혜이니 그것은 멸망을 방지하기 위함이다.", "핵심통찰":"책망을 받는 것은 저주가 아니라 은혜이다"}
    ],
    표6_설교자료: [
        {"대지":"제목", "내용":"레위와의 언약이 항상 있게 하려 - 경고 뒤에 숨은 사랑", "예화_적용":"하나님의 경고는 사랑의 다른 이름이다"},
        {"대지":"서론", "내용":"2-3절의 무서운 경고 뒤에 4절은 그 경고의 이유를 밝힌다. 놀랍게도 그 이유는 '언약의 보존'이다. 하나님은 제사장을 파괴하려는 것이 아니라 레위와의 언약을 지키시려는 것이다. 경고는 사랑의 표현이었다", "예화_적용":"사랑하기 때문에 바로잡으시는 하나님의 마음을 이해하라"},
        {"대지":"1대지: 이 명령을 내린 것은 (경고의 의도 공개)", "내용":"하나님이 직접 경고의 목적을 밝히심. 심판이 아니라 교정이 목적", "예화_적용":"부모의 꾸짖음이 사랑인 것처럼 하나님의 경고도 사랑이다"},
        {"대지":"2대지: 레위와 세운 나의 언약 (언약의 기억)", "내용":"비느하스의 열심에서 시작된 레위 언약. 하나님은 한번 세운 언약을 기억하신다", "예화_적용":"하나님은 우리와의 언약을 결코 잊지 않으신다"},
        {"대지":"3대지: 항상 있게 하려 함 (보존의 목적)", "내용":"언약이 '항상' 유지되도록 하시려는 하나님의 의도. 영원한 보존의 의지", "예화_적용":"하나님의 신실하심이 언약을 영원히 유지시킨다"},
        {"대지":"결론", "내용":"하나님의 가장 무서운 경고도 그 뒤에는 언약을 지키시려는 사랑이 있다. 징계를 받을 때 하나님의 사랑을 기억하고 회개로 반응하라", "예화_적용":"징계 앞에서 원망이 아닌 감사로 반응하는 것이 성숙한 신앙이다"}
    ],
