        {"항목":"형제간 궤사", "내용":"유다 남자들이 이스라엘 아내를 이혼하고 이방 여인과 결혼하는 행위. 같은 백성끼리의 배신", "목회적활용":"공동체 내부의 배신은 외부의 적보다 더 큰 상처를 남긴다"},
        {"항목":"열조의 언약", "내용":"시내산 언약을 포함한 하나님과 이스라엘의 모든 언약. 이혼과 이방 결혼으로 언약이 욕되게 됨", "목회적활용":"개인의 행동이 공동체 전체의 언약적 관계에 영향을 미친다"}
