        {"구절":"느 13:23-27", "연결점":"유다 사람들이 아스돗 암몬 모압 여인을 아내로 맞아들임", "구분":"구약"},
        {"구절":"계 18:4", "연결점":"내 백성아 거기서 나오라 그의 죄에 참여하지 말라", "구분":"신약"}
