        {"원어":"פָּנָה (파나)", "의미_문법":"돌아보다 - 동사 칼형. 관심을 기울이다", "설교포인트":"하나님이 돌아보시지 않는 예배는 공허하다"},
        {"원어":"רָצוֹן (라촌)", "의미_문법":"기쁨/기꺼이 - 명사. 하나님의 기쁘신 뜻", "설교포인트":"하나님이 기꺼이 받으시는 예배를 드리는 것이 목표여야 한다"}
