    표5_매튜헨리: [
        {"영어원문":"Covering the altar of the Lord with tears, with weeping, and with crying out. The tears of the wronged wives cried to heaven against their cruel husbands.", "한국어번역":"여호와의 단을 눈물과 울음과 부르짖음으로 덮도다. 억울한 아내들의 눈물이 잔인한 남편들을 하늘에 고소하였다.", "핵심통찰":"약자의 눈물은 하늘에 닿는 고소장이다"},
        {"영어원문":"Insomuch that he regardeth not the offering any more. God will not accept worship from those who abuse their families.", "한국어번역":"그러므로 그가 더 이상 제물을 돌아보지 않으시니. 하나님은 가정을 학대하는 자의 예배를 받지 않으신다.", "핵심통찰":"가정에서의 관계가 올바르지 않으면 예배도 거부된다"},
        {"영어원문":"Neither receiveth it with good will at your hand. Broken relationships make our worship unacceptable.", "한국어번역":"너희 손에서 기꺼이 받지도 않으시나니. 깨어진 관계가 우리의 예배를 받으실 수 없게 만든다.", "핵심통찰":"관계의 회복 없이는 참된 예배가 불가능하다"}
    ],
