        {"대지":"2대지: 다시는 돌아보지도 아니하시며 (거부된 예배)", "내용":"관계적 죄가 해결되지 않으면 예배가 거부됨. 돌아보다(파나)의 부정은 완전한 무시를 의미", "예화_적용":"화목 없이 드리는 예배는 하나님께 도달하지 못한다"},
        {"대지":"3대지: 기꺼이 받지도 아니하시거늘 (하나님의 기쁨이 없는 예배)", "내용":"'라촌'의 부정은 하나님이 기뻐하지 않으시는 예배를 의미. 형식은 있으나 기쁨이 없는 예배", "예화_적용":"하나님이 기뻐하시는 예배인지 점검해야 한다"},
        {"대지":"결론", "내용":"마태복음 5:23-24의 말씀이 이 구절의 신약적 적용이다. 형제와 화목한 후에 예물을 드리라. 관계의 회복이 예배의 전제 조건이다", "예화_적용":"예배 전에 깨어진 관계가 없는지 먼저 점검하라"}
