    표5_매튜헨리: [
        {"영어원문":"The Lord hath been witness between thee and the wife of thy youth. God saw the marriage vow and will hold you accountable.", "한국어번역":"여호와께서 너와 네 젊은 시절의 아내 사이에 증인이 되셨다. 하나님이 결혼 서약을 보셨고 책임을 물으실 것이다.", "핵심통찰":"하나님이 목격하신 약속은 반드시 책임이 따른다"},
        {"영어원문":"She is thy companion and the wife of thy covenant. The marriage relationship is both a companionship and a covenant.", "한국어번역":"그는 네 동반자요 네 언약의 아내이다. 결혼 관계는 동반자 관계이자 언약이다.", "핵심통찰":"결혼은 동반자 관계와 언약이라는 이중 구조"},
        {"영어원문":"Yet ye have dealt treacherously against her. To betray the partner of your youth is to betray God who witnessed the vow.", "한국어번역":"그런데 네가 그에게 궤사를 행하였다. 젊은 날의 동반자를 배신하는 것은 맹세를 목격하신 하나님을 배신하는 것이다.", "핵심통찰":"배우자에 대한 배신은 곧 하나님에 대한 배신이다"}
    ],
    표6_설교자료: [
        {"대지":"제목", "내용":"여호와께서 증거하셨음이니라 - 하나님이 증인이신 결혼", "예화_적용":"결혼은 하나님이 목격하시고 보증하시는 거룩한 언약이다"},
        {"대지":"서론", "내용":"유다 사람들이 '어찜이니까'라고 물을 때 하나님은 직접 이유를 밝히신다. 어려서 취한 아내를 버리고 이방 여인과 결혼한 죄다. 하나님은 결혼의 증인이시며 그 맹약을 기억하고 계신다", "예화_적용":"하나님은 우리의 약속을 잊지 않고 기억하고 계신다"},
        {"대지":"1대지: 여호와께서 증거하셨음이니라 (결혼의 증인이신 하나님)", "내용":"하나님이 결혼식의 증인이 되심. 결혼은 사람만의 약속이 아닌 하나님 앞의 언약", "예화_적용":"결혼 서약을 할 때 하나님이 그 자리에 계셨음을 기억하라"},
        {"대지":"2대지: 그는 네 짝이요 (인생의 동반자)", "내용":"'하베라'는 친구이자 동반자. 함께 인생을 살아가는 가장 가까운 사람", "예화_적용":"배우자를 인생의 가장 소중한 동반자로 대하라"},
        {"대지":"3대지: 너와 맹약한 아내로되 (언약의 신실함)", "내용":"결혼은 맹약이요 언약. 이 맹약을 깨는 것은 하나님과의 관계도 깨는 것", "예화_적용":"결혼의 맹약을 지키는 것이 하나님의 뜻을 행하는 것이다"},
        {"대지":"결론", "내용":"하나님은 모든 결혼의 증인이시다. 그분이 보시는 앞에서 맹약을 깨는 것이 얼마나 심각한지 깨달아야 한다. 어려서 취한 아내를 사랑하고 맹약을 지키는 것이 하나님을 기쁘시게 하는 것이다", "예화_적용":"처음 사랑의 맹세를 매일 새롭게 하라"}
    ],
