        {"상황":"마음을 다스리기 어려운 분", "성경원리":"'심령을 삼가 지키라'는 명령은 마음 수호가 모든 행동의 시작임을 가르침", "실제적용":"매일 아침 하나님 앞에서 마음을 점검하고 기도로 지키는 습관을 세우라"},
        {"상황":"결혼의 의미와 목적에 대해 혼란스러운 분", "성경원리":"결혼의 목적은 동반자 관계와 경건한 자손 양육. 하나님의 설계 안에서 의미를 찾아야 한다", "실제적용":"결혼의 목적을 세상적 기준이 아닌 성경적 기준으로 재정립하라"}
