        {"원어":"מִשְׁפָּט (미쉬파트)", "의미_문법":"공의/심판 - 명사. 올바른 판단과 정의", "설교포인트":"하나님의 공의를 의심하는 것은 하나님을 부인하는 것"},
        {"원어":"חָפֵץ (하페츠)", "의미_문법":"기쁨/기뻐하다 - 동사 칼형. 즐거워하다", "설교포인트":"하나님이 악을 기뻐하신다는 거짓말에 속지 말라"}
