        {"대지":"2대지: 악인이 하나님의 눈에 선하다는 거짓말 (하나님의 성품 왜곡)", "내용":"악인이 형통하는 것을 보고 하나님이 악을 좋아하신다고 단정. 하나님의 성품에 대한 심각한 왜곡", "예화_적용":"현실의 표면만 보고 하나님의 성품을 판단하지 말라"},
        {"대지":"3대지: 공의의 하나님이 어디 계시냐 (하나님의 존재 의심)", "내용":"공의가 실현되지 않는 것처럼 보일 때 하나님의 존재 자체를 의심. 가장 위험한 불신앙", "예화_적용":"하나님의 시간표는 우리의 시간표와 다르다. 인내하며 기다리라"},
        {"대지":"결론", "내용":"이 질문에 대한 하나님의 답은 3:1에서 시작된다. 언약의 사자가 오실 것이다. 공의의 하나님은 반드시 오신다. 그러나 그 오심이 은혜일지 심판일지는 우리의 태도에 달려 있다", "예화_적용":"하나님의 공의를 기다릴 때 인내와 신뢰가 필요하다"}
