        {"원어":"מַלְאַךְ הַבְּרִית (말라크 하베리트)", "의미_문법":"언약의 사자 - 명사 연계형. 언약을 성취하실 분", "설교포인트":"언약의 사자는 하나님의 모든 약속을 성취하시는 분이다"},
        {"원어":"חָפֵץ (하페츠)", "의미_문법":"사모하다/기뻐하다 - 동사 칼형. 간절히 원하다", "설교포인트":"사모하는 바가 이루어질 때 기쁨과 두려움이 함께 온다"}
