        {"항목":"길을 예비함", "내용":"고대 근동에서 왕이 행차할 때 선발대가 길을 닦고 정비했음. 영적 준비를 위한 선구자의 역할", "목회적활용":"위대한 일 앞에는 반드시 준비의 과정이 있다"},
        {"항목":"언약의 사자", "내용":"이스라엘이 오랫동안 기다리던 메시아적 인물. 하나님의 언약을 성취하고 완성하실 분", "목회적활용":"하나님의 약속은 반드시 성취된다. 그 시간표를 신뢰하라"}
