        {"영어원문":"He shall purify the sons of Levi. Even those who had been most corrupt should be reformed and refined.", "한국어번역":"레위의 자손을 깨끗케 하실 것이다. 가장 부패했던 자들도 개혁되고 정련될 것이다.", "핵심통찰":"가장 타락한 자도 하나님의 연단으로 회복될 수 있다"},
        {"영어원문":"That they may offer unto the Lord an offering in righteousness. The purpose of all the refining is that acceptable worship may be restored.", "한국어번역":"그들이 의로운 제물을 여호와께 드릴 것이다. 모든 연단의 목적은 하나님께 합당한 예배가 회복되는 것이다.", "핵심통찰":"연단의 궁극적 목적은 참된 예배의 회복이다"}
