        {"구절":"사 56:7", "연결점":"그들의 번제와 희생은 나의 단에서 기쁨이 되리니", "구분":"구약"},
        {"구절":"계 21:2-3", "연결점":"새 예루살렘이 하늘에서 내려오니 하나님이 사람들과 함께 거하시리라", "구분":"신약"}
