        {"원어":"מְנָאֲפִים (메나아핌)", "의미_문법":"간음하는 자들 - 분사 복수. 간통자", "설교포인트":"성적 부도덕은 하나님의 심판 목록의 핵심"},
        {"원어":"שָׂכִיר (사키르)", "의미_문법":"품군 - 명사. 일용 노동자", "설교포인트":"약자의 임금을 착취하는 것은 하나님의 심판 대상"},
        {"원어":"עֵד (에드)", "의미_문법":"증거/증인 - 명사. 법정 증인", "설교포인트":"하나님 자신이 심판의 증인이 되신다"}
