        {"항목":"속히 증거하리라", "내용":"하나님 자신이 증인이자 심판관이 되심. '속히'는 심판의 긴급성과 확실성을 강조", "목회적활용":"하나님의 심판은 반드시 오며, 우리가 생각하는 것보다 빠를 수 있다"},
        {"항목":"사회적 약자 보호", "내용":"품군, 과부, 고아, 나그네는 고대 이스라엘의 대표적 사회적 약자. 이들에 대한 억압이 심판 목록에 포함", "목회적활용":"사회적 약자를 돌보는 것이 하나님의 뜻이다"}
