        {"교리":"약자 보호의 신학", "설명":"과부, 고아, 나그네 보호는 구약 윤리의 핵심. 하나님은 약자의 편에 서시는 분", "관련구절":"출 22:22-24, 신 10:18, 시 68:5, 약 1:27"}
