        {"원어":"סֵפֶר זִכָּרוֹן (세페르 지카론)", "의미_문법":"기념책 - 명사구. 기억의 책, 기록의 책", "설교포인트":"하나님 앞에 우리의 모든 신실함이 기록되어 있다"},
        {"원어":"חֹשְׁבֵי (호쉐베)", "의미_문법":"생각하는 자들 - 분사 복수. 묵상하는, 존중히 여기는", "설교포인트":"하나님의 이름을 존중히 생각하는 것 자체가 경배이다"}
