    표2_역사적배경: [
        {"항목":"남은 자들의 교제", "내용":"불신앙이 만연한 시대에도 하나님을 경외하는 소수의 남은 자들이 서로 대화하며 격려. 소수의 신실한 자들", "목회적활용":"어두운 시대일수록 신앙의 공동체가 중요하다"},
        {"항목":"기념책", "내용":"페르시아 제국에서는 왕을 위해 공을 세운 자들의 이름을 기록하는 관행이 있었음 (에 6:1). 하나님도 신실한 자들을 기록하심", "목회적활용":"하나님은 우리의 신실함을 하나도 빠뜨리지 않고 기록하신다"},
        {"항목":"극적 전환", "내용":"13-15절의 어두운 불신앙에서 16절의 희망적 전환. 하나님을 경외하는 자들이 등장하며 분위기가 완전히 바뀜", "목회적활용":"가장 어두운 시대에도 빛이 되는 사람들이 있다"}
    ],
    표3_신학적의미: [
        {"교리":"남은 자 사상", "설명":"불신앙이 만연해도 하나님을 경외하는 남은 자가 항상 존재. 하나님은 이들을 특별히 주목하심", "관련구절":"왕상 19:18, 롬 11:4-5, 사 1:9, 습 3:12"},
        {"교리":"하나님의 기록", "설명":"기념책에 기록된다는 것은 하나님이 신실한 자들을 잊지 않으시며 반드시 보상하실 것을 의미", "관련구절":"출 32:32, 시 56:8, 단 12:1, 계 20:12"},
        {"교리":"경청하시는 하나님", "설명":"'분명히 들으시고'는 하나님이 우리의 대화까지 주의 깊게 듣고 계심을 보여줌. 인격적 관계의 하나님", "관련구절":"시 34:15, 시 116:1-2, 벧전 3:12, 잠 15:29"}
    ],
