        {"구분":"남은 자들의 교제", "내용":"어두운 시대의 신실한 소수", "그리스도연결":"두세 사람이 내 이름으로 모인 곳에 함께 계신 그리스도 (마 18:20)"},
        {"구분":"분명히 들으시는 하나님", "내용":"경외하는 자의 말을 경청하심", "그리스도연결":"아버지께서 항상 들으심을 아나이다 (요 11:42)"}
