    표4_예표론: [
        {"구분":"특별한 소유(세굴라)", "내용":"하나님의 개인적 보물로 선택됨", "그리스도연결":"그리스도가 자기 피로 사신 교회 (행 20:28, 엡 1:14)"},
        {"구분":"아들을 아끼듯", "내용":"아버지의 깊은 사랑으로 아끼심", "그리스도연결":"아바 아버지라 부르게 하시는 양자의 영 (롬 8:15, 갈 4:6)"},
        {"구분":"나의 정한 날", "내용":"하나님이 정하신 심판과 구원의 날", "그리스도연결":"그리스도의 재림과 최후 심판의 날 (행 17:31)"}
    ],
    표5_매튜헨리: [
        {"영어원문":"They shall be mine, saith the Lord, in that day when I make up my jewels. God's people are His jewels, His peculiar treasure.", "한국어번역":"그들이 나의 것이 되리라, 여호와의 말이니라, 내가 나의 보석을 만드는 그 날에. 하나님의 백성은 하나님의 보석이요 특별한 보물이다.", "핵심통찰":"하나님에게 있어 우리는 보석과 같은 특별한 보물"},
        {"영어원문":"I will spare them, as a man spareth his own son that serveth him. The tenderest relation in nature—a father and his dutiful son.", "한국어번역":"사람이 자기를 섬기는 아들을 아끼듯 내가 그들을 아끼리라. 자연에서 가장 부드러운 관계—아버지와 효도하는 아들.", "핵심통찰":"하나님의 보호는 아버지가 사랑하는 아들을 아끼는 것과 같다"},
        {"영어원문":"In that day when I make up my jewels. There is a day coming when God will publicly own and honour His faithful ones.", "한국어번역":"내가 보석을 만드는 그 날에. 하나님이 신실한 자들을 공개적으로 인정하시고 영광 돌리시는 날이 온다.", "핵심통찰":"하나님이 신실한 자를 공개적으로 인정하시는 날이 온다"}
    ],
    표6_설교자료: [
        {"대지":"제목", "내용":"나의 특별한 소유 - 하나님의 보물인 우리", "예화_적용":"하나님은 우리를 개인적 보물처럼 소중히 여기시고 아끼신다"},
        {"대지":"서론", "내용":"14절에서 '하나님 섬기는 것이 헛되다'고 한 자들에 대한 최종 답이 17절이다. 하나님을 섬기는 것은 결코 헛되지 않다. 하나님은 경외하는 자들을 '나의 특별한 소유(세굴라)'로 삼으시고, 아버지가 아들을 아끼듯 아끼시겠다고 약속하신다", "예화_적용":"하나님의 보물이라는 정체성이 모든 것을 바꾼다"},
        {"대지":"1대지: 나의 정한 날에 (하나님의 시간표)", "내용":"하나님이 정하신 날에 모든 것이 밝혀질 것. 지금은 보이지 않지만 그 날이 반드시 온다", "예화_적용":"하나님의 시간표를 신뢰하고 인내하라"},
        {"대지":"2대지: 나의 특별한 소유를 삼을 것이요 (보물의 정체성)", "내용":"'세굴라'는 왕의 개인적 보물. 모든 것을 가지신 하나님이 우리를 특별한 보물로 여기심", "예화_적용":"세상이 나를 어떻게 평가하든 하나님의 보물이라는 정체성을 잊지 말라"},
        {"대지":"3대지: 아들을 아낌 같이 아끼리니 (아버지의 사랑)", "내용":"아버지가 효도하는 아들을 아끼는 가장 따뜻한 비유. 하나님의 사랑은 차갑지 않고 따뜻하다", "예화_적용":"하나님은 냉정한 심판관이 아니라 따뜻한 아버지이시다"},
        {"대지":"결론", "내용":"하나님을 섬기는 것이 헛되지 않은 이유가 여기에 있다. 하나님은 경외하는 자를 보물로 여기시고, 기념책에 기록하시고, 아들처럼 아끼신다. 이보다 더 큰 보상이 있겠는가?", "예화_적용":"하나님의 보물로 살아가는 것이 인생 최고의 축복이다"}
    ],
