        {"새찬송가":"545", "통일찬송가":"367", "제목":"하나님의 크신 사랑", "선정이유":"보물처럼 아끼시는 하나님의 사랑"},
        {"새찬송가":"310", "통일찬송가":"255", "제목":"예수를 나의 구주 삼고", "선정이유":"하나님의 자녀 된 신분의 확신"},
        {"새찬송가":"440", "통일찬송가":"351", "제목":"나를 지으신 주 하나님", "선정이유":"보물로 만드신 하나님의 손길"}
