        {"교리":"영적 시력의 회복", "설명":"하나님께 돌아올 때 선악을 분별하는 영적 시력이 회복됨. 시편 73편의 시인이 성소에서 깨달은 것과 같음", "관련구절":"시 73:17, 요 9:25, 엡 1:18, 행 26:18"},
        {"교리":"두 길의 교리", "설명":"의인과 악인, 섬기는 자와 아닌 자의 이원적 구분. 시편 1편의 두 길 교리와 일치", "관련구절":"시 1:1-6, 마 7:13-14, 신 30:19, 렘 21:8"}
