        {"항목":"만군의 여호와", "내용":"'만군의 여호와의 말이니라'로 선언을 마무리. 이 약속의 보증인이 만군의 주재이심을 강조", "목회적활용":"약속의 확실성을 만군의 여호와의 권위로 보증"}
