        {"대지":"2대지: 재 같이 되리라 (악의 완전한 소멸)", "내용":"4:1의 불에 탄 결과 재만 남음. 한때 강했던 악이 한줌의 재로 변함", "예화_적용":"아무리 강해 보이는 악도 하나님 앞에서는 한줌의 재에 불과하다"},
        {"대지":"3대지: 만군의 여호와의 말이니라 (약속의 보증)", "내용":"이 약속의 보증인은 만군의 여호와. 천군을 거느린 전능자의 선언", "예화_적용":"이 약속은 인간의 소망이 아니라 전능자의 선언이다"},
        {"대지":"결론", "내용":"악에 대한 최종 승리는 이미 선언되었다. 우리는 결과를 모르는 전쟁을 싸우는 것이 아니라 이미 승리가 확정된 전쟁에 참여하는 것이다. 만군의 여호와께서 보증하셨다", "예화_적용":"승리가 확정된 전쟁에서 두려워할 이유가 없다"}
