        {"구절":"마 17:12", "연결점":"엘리야가 이미 왔으되 사람들이 알지 못하고", "구분":"신약"},
        {"구절":"행 2:20", "연결점":"주의 크고 영화로운 날이 이르기 전에", "구분":"신약"}
